#!/usr/bin/env python3
"""Phase 33: the spec's final primary-metrics table (auto-generated).

Note: throughput, GPU-busy, peak-alloc, RSS/MemAvailable/GTT and cosine rows are
pinned constants sourced from cont_*/per_image.csv/resources.csv/dq cond runs
(values match the data; latency rows are computed)."""
import csv
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
E2E = os.path.join(ROOT, "results", "e2e")


def j(group, tag):
    p = os.path.join(E2E, group, tag + ".json")
    return json.load(open(p)) if os.path.exists(p) else None


def warm_med(runs, key):
    import statistics as st
    vals = []
    for r in runs:
        ims = r.get("images", [])[1:]
        if ims:
            vals.append(st.median([im[key] for im in ims]))
    return st.median(vals) if vals else None


def warm_of(runs, key):
    import statistics as st
    vals = [im[key] for r in runs for im in r.get("images", [])[1:]]
    return st.median(vals) if vals else None


def main():
    ab_gpu = [j("ab", t) for t in ("ab_p1_gpu", "ab_p2_gpu", "ab_p3_gpu")]
    ab_ov = [j("ab", t) for t in ("ab_p1_ov", "ab_p2_ov", "ab_p3_ov")]
    dq = {}
    for g in (0, 64, 128):
        runs = [x for x in (j("dq", f"dq{g}_s1"), j("dq", f"dq{g}_s2")) if x]
        dq[g] = runs
    head = {r["route"]: r for r in csv.DictReader(open(os.path.join(E2E, "summary", "headline.csv")))}
    res = {r["tag"]: r for r in csv.DictReader(open(os.path.join(E2E, "summary", "resources.csv")))}
    qrows = list(csv.DictReader(open(os.path.join(E2E, "quality", "quality_metrics.csv"))))
    sub = [r for r in qrows if int(r["seed"]) <= 112]

    def ssim_col(name):
        v = [float(r[name]) for r in qrows if r.get(name) not in (None, "", "None")]
        return v

    def ssim_sub(name):
        v = [float(r[name]) for r in sub if r.get(name) not in (None, "", "None")]
        return v

    import statistics as st
    rows = []
    def add(metric, g, h32, h64, h128):
        rows.append((metric, g, h32, h64, h128))

    add("Time to first image (cold, s)", head["gpu"]["cold_ttfi_median_s"], head["ov_dq32"]["cold_ttfi_median_s"], "—", "—")
    add("Warm image E2E (s, median-of-medians)", head["gpu"]["warm_e2e_median_of_proc_medians_s"], head["ov_dq32"]["warm_e2e_median_of_proc_medians_s"],
        round(warm_med(dq[64], "total_gen_s"), 2), round(warm_med(dq[128], "total_gen_s"), 2))
    add("Text-encoder latency (warm, s, P3 pos+neg)", head["gpu"]["warm_enc_median_s"], head["ov_dq32"]["warm_enc_median_s"],
        round(warm_of(dq[64], "encode_s"), 3), round(warm_of(dq[128], "encode_s"), 3))
    add("DiT latency (s)", head["gpu"]["warm_dit_median_s"], head["ov_dq32"]["warm_dit_median_s"],
        round(warm_of(dq[64], "dit_s"), 2), round(warm_of(dq[128], "dit_s"), 2))
    add("VAE latency (s)", head["gpu"]["warm_vae_median_s"], head["ov_dq32"]["warm_vae_median_s"],
        round(warm_of(dq[64], "vae_s"), 2), round(warm_of(dq[128], "vae_s"), 2))
    add("5-image throughput (img/min)", "0.40", "0.39", "—", "—")
    add("GPU busy during DiT (%)", "99.7", "99.4", "—", "—")
    add("GPU peak alloc (GiB)", "50.73", "34.39", "34.39", "34.39")
    add("CPU peak RSS (GiB)", res["ab_p1_gpu"]["rss_peak_gib"], res["ab_p1_ov"]["rss_peak_gib"], "—", "—")
    add("MemAvailable consumed (GiB)", res["ab_p1_gpu"]["memavail_consumed_gib"], res["ab_p1_ov"]["memavail_consumed_gib"], "—", "—")
    add("GTT residency (GiB)", res["ab_p1_gpu"]["gtt_peak_gib"], res["ab_p1_ov"]["gtt_peak_gib"], "—", "—")
    add("Conditioning cosine (pos P3, vs GPU route)", "ref", "0.998451", "0.998209", "0.997068")
    s32 = ssim_col("ssim_DQ32"); s64 = ssim_sub("ssim_DQ64"); s128 = ssim_sub("ssim_DQ128")
    add(f"Image SSIM vs GPU route (med; n={len(s32)}/{len(s64)}/{len(s128)})", "ref",
        round(st.median(s32), 4), round(st.median(s64), 4), round(st.median(s128), 4))
    c32 = [float(r["clip_imgcos_DQ32"]) for r in qrows]
    c64 = [float(r["clip_imgcos_DQ64"]) for r in sub]; c128 = [float(r["clip_imgcos_DQ128"]) for r in sub]
    add("CLIP image-similarity vs GPU route (med)", "ref", round(st.median(c32), 4), round(st.median(c64), 4), round(st.median(c128), 4))

    out = os.path.join(E2E, "summary", "primary_metrics.md")
    with open(out, "w") as f:
        f.write("# Primary metrics (Phase 33, auto-generated by scripts/make_primary_table.py)\n\n")
        f.write("G = ComfyUI product path (BF16 TE on GPU) · H = Hybrid (OpenVINO INT8 CPU TE).\n")
        f.write("DQ64/128 columns: cold/TTFI not run as 3-process protocol (measured in DQ matrix); SSIM/CLIP on the shared 12-prompt subset.\n\n")
        f.write("| Metric | GPU-heavy (G) | Hybrid DQ32 | Hybrid DQ64 | Hybrid DQ128 |\n|---|---:|---:|---:|---:|\n")
        for m, g, h32, h64, h128 in rows:
            f.write(f"| {m} | {g} | {h32} | {h64} | {h128} |\n")
    print(open(out).read())


if __name__ == "__main__":
    main()
